const boot=document.getElementById('boot');setTimeout(()=>boot.classList.add('hidden'),1900);const startBtn=document.getElementById('startBtn');const startMenu=document.getElementById('startMenu');const toast=document.getElementById('toast');const toastText=document.getElementById('toastText');let topZ=300;function bringToFront(win){topZ+=1;win.style.zIndex=topZ;document.querySelectorAll('.window').forEach(w=>w.classList.remove('foreground'));win.classList.add('foreground');}function centerWindow(win){if(window.innerWidth<=780){win.style.left='';win.style.top='';win.style.transform='';return;}const rect=win.getBoundingClientRect();const width=rect.width||Math.min(820,window.innerWidth-24);const height=rect.height||Math.min(560,window.innerHeight*.78);const left=Math.max(8,(window.innerWidth-width)/2);const top=Math.max(8,(window.innerHeight-height)/2);win.style.left=left+'px';win.style.top=top+'px';win.style.transform='none';}function openWindow(id){const target=document.getElementById(id);if(!target)return;target.classList.add('show');if(!target.dataset.positioned){requestAnimationFrame(()=>{centerWindow(target);target.dataset.positioned='true';});}bringToFront(target);startMenu.classList.remove('show');}document.querySelectorAll('[data-open]').forEach(el=>{el.addEventListener('click',()=>openWindow(el.dataset.open));});document.querySelectorAll('.window').forEach(win=>{const titlebar=win.querySelector('.titlebar');if(!titlebar)return;let dragging=false;let offsetX=0;let offsetY=0;win.addEventListener('pointerdown',()=>bringToFront(win));titlebar.addEventListener('pointerdown',(e)=>{if(window.innerWidth<=780||e.pointerType==='touch')return;if(e.target.closest('button'))return;bringToFront(win);const rect=win.getBoundingClientRect();dragging=true;offsetX=e.clientX-rect.left;offsetY=e.clientY-rect.top;win.classList.add('dragging');win.style.left=rect.left+'px';win.style.top=rect.top+'px';win.style.transform='none';titlebar.setPointerCapture(e.pointerId);e.preventDefault();});titlebar.addEventListener('pointermove',(e)=>{if(!dragging)return;const rect=win.getBoundingClientRect();const maxLeft=Math.max(0,window.innerWidth-Math.min(rect.width,window.innerWidth));const maxTop=Math.max(0,window.innerHeight-48);let left=e.clientX-offsetX;let top=e.clientY-offsetY;left=Math.min(Math.max(left,-rect.width+120),maxLeft);top=Math.min(Math.max(top,0),maxTop);win.style.left=left+'px';win.style.top=top+'px';});function stopDrag(e){if(!dragging)return;dragging=false;win.classList.remove('dragging');if(titlebar.hasPointerCapture?.(e.pointerId)){titlebar.releasePointerCapture(e.pointerId);}}titlebar.addEventListener('pointerup',stopDrag);titlebar.addEventListener('pointercancel',stopDrag);});document.querySelectorAll('.close').forEach(btn=>{btn.addEventListener('click',()=>{const win=btn.closest('.window');if(win)win.classList.remove('show');});});startBtn.addEventListener('click',(e)=>{e.stopPropagation();startMenu.classList.toggle('show');});document.addEventListener('click',(e)=>{if(!startMenu.contains(e.target)&&e.target!==startBtn){startMenu.classList.remove('show');}});const projectData={pfuschdb:{title:'pfuschDB',type:'Full Stack Platform',desc:'A platform for finding local workers, rating them and communicating with them.',chips:['Vue.js','Spring Boot','MySQL'],link:'https://gitlab.com/pfuschdb/pfuschdb-projekt/-/tree/danijel?ref_type=heads'},cinema:{title:'Cinema Management',type:'Backend Project',desc:'Backend system for managing cinemas, auditoriums, movies and schedules.',chips:['Java','Spring Boot','REST'],link:'https://gitlab.com/dsimic-projects/backend/cinema'},webshop:{title:'Webshop',type:'Frontend Project',desc:'Responsive Vue.js webshop with product browsing and checkout functionality.',chips:['Vue.js','JavaScript','Frontend'],link:'https://gitlab.com/dsimic-projects/frontend/webshop'},spring:{title:'Spring Boot Generator',type:'Developer Tool',desc:'Generates common Spring Boot structures and boilerplate code.',chips:['Java','Spring Boot','Tooling'],link:'https://danijelsimic.github.io/spring-generator'},currency:{title:'Currency Converter',type:'Web App',desc:'Real-time currency conversion using an exchange-rate API.',chips:['JavaScript','REST API','Frontend'],link:'https://danijelsimic.github.io/converter'},api:{title:'API Client Generator',type:'Developer Tool',desc:'Generates Axios client code from an endpoint and selected HTTP method.',chips:['JavaScript','Axios','API'],link:'https://danijelsimic.github.io/api-generator'}};document.querySelectorAll('[data-project]').forEach(item=>{item.addEventListener('click',()=>{const p=projectData[item.dataset.project];document.getElementById('projectTitle').textContent=p.type;document.getElementById('projectName').textContent=p.title;document.getElementById('projectDescription').textContent=p.desc;document.getElementById('projectLink').href=p.link;document.getElementById('projectChips').innerHTML=p.chips.map(c=>`<span class="chip">${c}</span>`).join('');openWindow('projectDetail');});});let toastTimer;function showToast(message){toastText.textContent=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2600);}const xpError=document.getElementById('xpError');const xpErrorTitle=document.getElementById('xpErrorTitle');const xpErrorText=document.getElementById('xpErrorText');const xpErrorOk=document.getElementById('xpErrorOk');const xpErrorClose=document.getElementById('xpErrorClose');const errorMessages=[['Illegal operation','This button looked functional, but Danijel never gave it a job.'],['Windows has encountered a problem','You clicked something from 2001. Please lower your expectations accordingly.'],['Critical developer exception','PEBKAC detected: Problem Exists Between Keyboard And Chair. Just kidding 😄'],['Access denied','Nice try. Administrator privileges require one coffee and two approvals.'],['Feature not found','This feature will be available right after TODO: fix later is completed.'],['Unexpected user input','DanijelOS was not emotionally prepared for that click.']];function showXpError(customTitle,customText){let title=customTitle;let text=customText;if(!title||!text){const pick=errorMessages[Math.floor(Math.random()*errorMessages.length)];title=pick[0];text=pick[1];}xpErrorTitle.textContent=title;xpErrorText.textContent=text;xpError.classList.add('show');}function closeXpError(){xpError.classList.remove('show');}xpErrorOk.addEventListener('click',closeXpError);xpErrorClose.addEventListener('click',closeXpError);document.querySelectorAll('.menu span').forEach(item=>{item.addEventListener('click',()=>{showXpError(item.textContent+' menu error','DanijelOS could not complete this operation because this menu is purely decorative. Very 2001.');});});document.querySelector('.desktop').addEventListener('contextmenu',(e)=>{if(e.target.closest('.desktop-icon')||e.target.closest('.window'))return;e.preventDefault();showXpError('Desktop error','Right-click menu not installed. Please insert Windows XP CD-ROM and try again.');});document.getElementById('clock').addEventListener('click',()=>{showToast('You clicked a clock for absolutely no reason.');});let photoClicks=0;document.getElementById('profileImage').addEventListener('click',()=>{photoClicks++;if(photoClicks===5){showToast('Developer mode enabled. Nothing happened, but it felt important.');photoClicks=0;}});window.addEventListener('resize',()=>{if(window.innerWidth<=780){document.querySelectorAll('.window').forEach(win=>{win.style.left='';win.style.top='';win.style.transform='';win.dataset.positioned='';});}});function updateClock(){const now=new Date();document.getElementById('clock').textContent=String(now.getHours()).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0');}updateClock();setInterval(updateClock,10000);